        display: inline-flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 18px;
        padding: 8px 12px;
        border-radius: 999px;
        background: rgba(37, 99, 235, 0.1);
        color: var(--primary-dark);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 0 0 14px;
        font-size: clamp(2rem, 4vw, 3.25rem);
