        margin: 0;
        max-width: 34rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .support-points {
        margin: 32px 0 0;
        padding: 0;
        list-style: none;
        display: grid;
        gap: 14px;
      }

      .support-points li {
        display: flex;
        gap: 12px;
        align-items: flex-start;
        color: var(--muted);
      }

      .support-points strong {
        display: block;
        margin-bottom: 4px;
        color: var(--text);
      }

      .point-icon {
        flex: 0 0 auto;
        width: 32px;
        height: 32px;
        display: inline-grid;
        place-items: center;
        border-radius: 10px;
        background: rgba(37, 99, 235, 0.12);
        color: var(--primary);
        font-weight: 700;
      }

      .form-panel {
        padding: 40px 32px;
        background: linear-gradient(180deg, #ffffff, #f8fbff);
      }

      .panel-title {
        margin: 0 0 10px;
        font-size: 1.4rem;
      }

      .panel-text {
        margin: 0 0 24px;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
        font-size: 0.95rem;
      }

      input {
        width: 100%;
        padding: 14px 15px;
        border: 1px solid rgba(148, 163, 184, 0.45);
        border-radius: 14px;
        background: #fff;
        color: var(--text);
        font: inherit;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
      }

      input::placeholder {
        color: #94a3b8;
      }

      input:focus {
        outline: none;
        border-color: rgba(37, 99, 235, 0.7);
        box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.88rem;
        line-height: 1.5;
      }

      .error-text {
        min-height: 1.2em;
        margin: 0;
        color: var(--danger);
        font-size: 0.88rem;
        font-weight: 600;
      }

      .has-error input {
        border-color: rgba(220, 38, 38, 0.5);
        background: var(--danger-soft);
      }

      .submit-button {
        margin-top: 8px;
        border: 0;
        border-radius: 14px;
        padding: 14px 18px;
        background: linear-gradient(135deg, var(--primary), #3b82f6);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
        box-shadow: 0 16px 28px rgba(37, 99, 235, 0.22);
      }

      .submit-button:hover {
        transform: translateY(-1px);
        background: linear-gradient(135deg, var(--primary-dark), var(--primary));
      }

      .submit-button:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.28);
        outline-offset: 2px;
      }

      .status-message {
        min-height: 1.4em;
        margin: 2px 0 0;
        font-weight: 600;
        color: #047857;
      }

      @media (max-width: 820px) {
        .support-card {
          grid-template-columns: 1fr;
        }

        .support-copy,
        .form-panel {
          padding: 32px 24px;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>

    <script>
      const appRoot = document.getElementById("app");

      function h(tag, props = {}, ...children) {
        const element = document.createElement(tag);

        Object.entries(props).forEach(([key, value]) => {
          if (key === "className") {
            element.className = value;
          } else if (key === "text") {
            element.textContent = value;
          } else if (key.startsWith("on") && typeof value === "function") {
            element.addEventListener(key.slice(2).toLowerCase(), value);
          } else if (value !== undefined && value !== null) {
            element.setAttribute(key, value);
          }
        });

        children.flat().forEach((child) => {
          if (child === null || child === undefined || child === false) {
            return;
          }

          element.appendChild(
            child instanceof Node ? child : document.createTextNode(String(child))
          );
        });

        return element;
      }

      function validateField(name, value) {
        const trimmed = value.trim();

        if (name === "fullName") {
          if (!trimmed) {
            return "Please enter your full name.";
          }
        }

        if (name === "email") {
          if (!trimmed) {
            return "Please enter your email address.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(trimmed)) {
            return "Enter a valid email address.";
          }
        }

        if (name === "phone" && trimmed) {
          const phonePattern = /^\+?[0-9\s\-().]{7,20}$/;
          if (!phonePattern.test(trimmed)) {
            return "Use a valid phone number format.";
          }
        }

        return "";
      }

      function InputField({
        id,
        name,
        label,
        type,
        placeholder,
        required = false,
        helperText = "",
        error = ""
      }) {
        const helperId = helperText ? id + "-helper" : "";
        const errorId = id + "-error";
        const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

        return h(
          "div",
          { className: "form-field" + (error ? " has-error" : "") },
          h("label", { for: id, text: label + (required ? " *" : "") }),
          h("input", {
