          h(
            "li",
            {},
            h("span", { className: "point-icon", "aria-hidden": "true", text: "24" }),
            h(
              "div",
              {},
              h("strong", { text: "Fast response windows" }),
              "Reach the support team with the key details they need to help quickly."
            )
          ),
          h(
            "li",
            {},
            h("span", { className: "point-icon", "aria-hidden": "true", text: "AI" }),
            h(
              "div",
              {},
              h("strong", { text: "Clear routing" }),
              "Required details keep requests easy to triage while optional phone contact stays flexible."
            )
          )
        );
      }

      function SupportContactForm() {
        return h(
          "section",
          { className: "support-card", "aria-labelledby": "support-heading" },
          h(
            "div",
            { className: "support-copy" },
            h("div", { className: "eyebrow", text: "Support team" }),
            h("h1", { id: "support-heading", text: "Tell us what you need." }),
            h(
              "p",
              {
                className: "lead",
                text:
                  "Share your contact details and our product support team will follow up with the best next step."
              }
            ),
            SupportHighlights()
          ),
          h(
            "div",
            { className: "form-panel" },
            h("h2", { className: "panel-title", text: "Contact support" }),
            h(
              "p",
              {
                className: "panel-text",
                text:
                  "Full name and email address are required so we can respond. Phone number is optional."
              }
            ),
            h(
              "form",
              { id: "support-form", novalidate: "true" },
              InputField({
                id: "fullName",
                name: "fullName",
                label: "Full name",
                type: "text",
                placeholder: "Jordan Lee",
                required: true
              }),
              InputField({
                id: "email",
                name: "email",
                label: "Email address",
                type: "email",
                placeholder: "jordan@example.com",
                required: true
              }),
              InputField({
                id: "phone",
                name: "phone",
                label: "Phone number",
                type: "tel",
                placeholder: "+1 (555) 123-4567",
                helperText: "Expected format: +1 (555) 123-4567 or similar."
              }),
              h("button", { type: "submit", className: "submit-button", text: "Submit" }),
              h("p", {
                id: "form-status",
                className: "status-message",
                "aria-live": "polite"
              })
            )
          )
        );
      }

